#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
F1="$GSZ/routes/adminCatalog.js"
F2="$GSZ/views/admin/product_edit.ejs"
TS=$(date +%Y%m%d-%H%M%S)
BK1="$F1.bak-step191-$TS"; BK2="$F2.bak-step191-$TS"
echo "==> step191: Product editor preserves each plan's fulfilment mapping (id-aware upsert)"
cp "$F1" "$BK1"; cp "$F2" "$BK2"; echo "    backups: $BK1 , $BK2"
restore(){ echo "!! restoring"; cp "$BK1" "$F1" 2>/dev/null||true; cp "$BK2" "$F2" 2>/dev/null||true; }
trap 'restore' ERR
echo "==> applying patcher"
P=$(mktemp /tmp/p191.XXXXXX.js); echo "" | base64 -d > "$P"
NODE_PATH="$GSZ/node_modules" node "$P" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$F1" && echo "    adminCatalog.js ok"
NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$F2','utf8'),{filename:'$F2'});console.log('    ejs ok: product_edit.ejs')"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$P"; trap - ERR
echo ""
echo "==> step191 OK  Editing a product's plans/prices now preserves each plan's bot/inventory mapping (plan_key, sku, source) and its row id — no more wiped mappings or orphaned inventory. Next: seed the two player duration plans."
